const discrete_affects = Function[discrete_affect_1, discrete_affect_2, discrete_affect_3, discrete_affect_4, discrete_affect_5, discrete_affect_6]

const discrete_event_times = Vector{Float64}[Float64[100.0, 250.0, 400.0, 550.0], Float64[150.0, 300.0, 450.0, 600.0], Float64[700.0], Float64[750.0], Float64[700.0], Float64[750.0]]

const discrete_event_preset = Bool[true, true, true, true, true, true]

const discrete_event_condition = Int64[0, 0, 0, 0, 0, 0]

const discrete_event_recheck = Bool[false, false, false, false, false, false]

const n_discrete_conditions = 0

const continuous_affects = Function[]

"    StandaloneSystem\n\nThe symbolic system of the exported problem: the names of its states and parameters, and of\nits observed quantities.\n"
struct StandaloneSystem{C}
    cache::C
    observed_index::Dict{Symbol, Int}
end

const system = StandaloneSystem(SymbolCache(state_names, param_names, :t), Dict{Symbol, Int}((name => i for (i, name) = enumerate(observed_names))))

const SII = SymbolicIndexingInterface

function SII.symbolic_container(sys::StandaloneSystem)
    sys.cache
end

function SII.is_observed(sys::StandaloneSystem, sym)
    sym isa Symbol && haskey(sys.observed_index, sym)
end

function SII.observed(sys::StandaloneSystem, sym::Symbol)
    f = observed_functions[sys.observed_index[sym]]
    (u, p, t)->begin
            f(u, p, t)
        end
end

function SII.observed(sys::StandaloneSystem, syms::Union{AbstractVector{Symbol}, Tuple{Vararg{Symbol}}})
    fs = map((sym->begin
                    SII.observed(sys, sym)
                end), syms)
    (u, p, t)->begin
            map((f->begin
                        f(u, p, t)
                    end), fs)
        end
end

function SII.observed(f::ODEFunction{iip, spec, typeof(rhs!)}, sym::Symbol) where {iip, spec}
    SII.observed(f.sys, sym)
end

function SII.observed(f::SDEFunction{iip, spec, typeof(rhs!)}, sym::Symbol) where {iip, spec}
    SII.observed(f.sys, sym)
end

function SII.get_all_timeseries_indexes(sys::StandaloneSystem, sym)
    if SII.is_observed(sys, sym)
        Set([SII.ContinuousTimeseries()])
    else
        SII.get_all_timeseries_indexes(sys.cache, sym)
    end
end

function SII.all_symbols(sys::StandaloneSystem)
    vcat(SII.all_symbols(sys.cache), observed_names)
end

"The preset discrete events of each of their times."
const preset_events = let preset = Dict{Float64, Vector{Int}}()
            for k = eachindex(discrete_event_times), tk = discrete_event_times[k]
                push!(get!(Vector{Int}, preset, tk), k)
            end
            preset
        end

"The discrete events that are not tied to fixed times, and so can be due at any time."
const unscheduled_events = findall(!, discrete_event_preset)

"    due_events(u, p, t) -> (due, at_time)\n\nWhether each discrete event is due at the state `u` and time `t`, and whether each is at one\nof its times. An event is due when the solver is at one of its times (or at any time, if it\nhas none) and its condition holds.\n"
function due_events(u, p, t)
    n = length(discrete_affects)
    at_time = falses(n)
    due = falses(n)
    for k = unscheduled_events
        at_time[k] = true
    end
    for k = get(preset_events, t, ())
        at_time[k] = true
    end
    any(at_time) || return (due, at_time)
    conds = discrete_conditions(u, p, t)
    for k = 1:n
        due[k] = at_time[k] && event_holds(k, conds)
    end
    (due, at_time)
end

"The values of the conditions of the discrete events that have one."
function discrete_conditions(u, p, t)
    conds = Vector{Bool}(undef, n_discrete_conditions)
    n_discrete_conditions > 0 && discrete_conditions!(conds, u, p, t)
    conds
end

"Whether the condition of the discrete event `k` holds, given the values `conds` of the conditions."
function event_holds(k, conds)
    discrete_event_condition[k] == 0 || conds[discrete_event_condition[k]]
end

"    discrete_callback()\n\nThe callback applying the discrete events. It fires when some event is due, and then applies\nthe events in order. Their conditions are evaluated before any of them is applied, except\nthat the events marked `recheck` evaluate theirs again when their turn comes, and are\napplied according to that.\n"
function discrete_callback()
    isempty(discrete_affects) && return nothing
    function condition(u, t, integrator)
        any(first(due_events(u, integrator.p, t)))
    end
    function affect!(integrator)
        (due, at_time) = due_events(integrator.u, integrator.p, integrator.t)
        for k = eachindex(discrete_affects)
            if discrete_event_recheck[k]
                at_time[k] || continue
                event_holds(k, discrete_conditions(integrator.u, integrator.p, integrator.t)) || continue
            else
                due[k] || continue
            end
            (discrete_affects[k])(integrator)
        end
        nothing
    end
    DiscreteCallback(condition, affect!)
end

"The callback applying the continuous events."
function continuous_callback()
    n = length(continuous_affects)
    n == 0 && return nothing
    function condition(out, u, t, integrator)
        continuous_roots!(out, u, integrator.p, t)
    end
    function affect!(integrator, event)
        if event isa Integer
            (continuous_affects[event])(integrator)
        else
            for idx = eachindex(event)
                event[idx] == 0 && continue
                (continuous_affects[idx])(integrator)
            end
        end
        nothing
    end
    VectorContinuousCallback(condition, affect!, n)
end

"The callbacks implementing the events of the model."
function callbacks()
    CallbackSet(continuous_callback(), discrete_callback())
end

"    problem(tspan=tspan; u0=u0, p=p0, callback=nothing, tstops=tstops, kwargs...)\n\nThe `ODEProblem` of the model over `tspan`, starting from the states `u0` with the parameters `p`.\nThe events of the model are part of the problem. `callback` adds further callbacks to them, and\nthe other keyword arguments are passed on to the problem.\n"
function problem(tspan = tspan; u0 = u0, p = p0, callback = nothing, tstops = tstops, kwargs...)
    cb = CallbackSet(callbacks(), callback)
    f = ODEFunction{true, SciMLBase.FullSpecialize}(rhs!; sys = system)
    ODEProblem(f, copy(u0), tspan, copy(p); callback = cb, tstops, kwargs...)
end

end # module
